//! `bsc session` (#architect-starts-and-stops-system-sessions) — the app side of start · stop · list
//! for the app-owned SYSTEM SESSIONS.
//!
//! ```text
//! bsc session list          → request file → watcher → answered HERE, in Rust (liveness is PtyState)
//! bsc session start|stop    → request file → watcher → emit `bsc://session-lifecycle`
//!                           → the frontend opens/closes the studio → invokes `system_session_ack`
//! ```
//!
//! ## Why the split
//! Liveness is a pure Rust fact — the same `pane_liveness` walk `bsc fleet list` reports from, so the
//! two commands cannot disagree about what is running. Bringing a studio UP is not: `openStudio` marks
//! it wanted and `StudioSessionHosts` mounts its `TerminalSlot`, which is zustand state Rust cannot
//! touch. Same shape as `fleet::wake`, for the same reason.
//!
//! ## Why the id is re-resolved here
//! The CLI already refuses anything outside the closed set. This resolves it AGAIN before acting,
//! because the channel is a directory any process can write to — treating the CLI as the only writer
//! would make the mitigation a convention rather than a boundary. The closed set is the whole reason
//! this verb is safe to grant the architect, so it is enforced on both sides of the wire.
//!
//! ## Why RUNNING is not just "wanted"
//! A studio is "running" when the frontend wants it (its mount is up) OR a PTY still exists for its
//! pane. Those can disagree: `TerminalView`'s unmount deliberately leaves the backend session alive so
//! a tab-switch reconnects rather than respawns, so a stray PTY can outlive the mount. Reporting on
//! `wanted` alone would tell a caller "not running" while a `claude` process was still up — and then
//! `stop` would leave it there. So Rust measures the PTY, the frontend knows the mount, and the
//! outcome is decided from both.

use bsc_session::{
    LifecycleAction, LifecycleRequest, LifecycleResult, SessionListRequest, SessionListResult,
    SystemSessionState,
};
use serde::Deserialize;
use std::time::Duration;
use tauri::{Emitter, Manager};

/// Shorter than the CLI's timeout so the caller gets our real error ("the frontend did not ack")
/// rather than a bare timeout that reads as "the app is not running".
const ACK_TIMEOUT: Duration = Duration::from_millis(5_000);

/// THE TECHNOLOGY AXIS — which technologies each partitioned studio's store actually holds
/// (`the-studio-session-set-is-derived-not-declared`).
///
/// This is the half `bsc-session` structurally cannot answer. That crate is Tauri-free and the CLI it
/// serves is a separate process holding no store open, so it can PARSE `librarianRust` but not know
/// whether rust has anything to curate. The app has both stores already, so the derivation lives
/// here and the projection is fed from it.
///
/// The two axes read at DIFFERENT LEVELS, which is why this is two arms and not one generic filter:
/// an algorithms implementation carries `tech` directly, while a component carries it via its KIT.
/// That asymmetry is the same one `studioScopeDirective` writes out on the frontend.
///
/// # It is deliberately fail-SOFT
///
/// A store that will not open yields no technologies for that kind rather than an error. The caller
/// is `bsc session list` and the lifecycle boundary, and the honest failure there is "that studio is
/// not among the ones that exist", which reads correctly. Failing the whole read instead would take
/// out the architect and the sound designer — neither of which has an axis at all — because a kit
/// directory was missing.
fn studio_axis(kind: &str) -> Vec<String> {
    let mut techs: Vec<String> = match kind {
        // `impl.tech`, straight off the algorithms graph — the same read `bsc graph impl list --tech`
        // filters on, so the librarian that exists is exactly the librarian that has a partition.
        "librarian" => bsc_graph::implementations()
            .iter()
            .filter_map(|im| im.get("tech").and_then(|t| t.as_str()).map(str::to_string))
            .collect(),
        // `kit.tech`, off the component library's KIT collection — one level up, because that is where
        // the component store carries the partition. `BSC_COMPONENT_KIT_DIR` is honoured for parity
        // with `bsc ui kit list`, which is the surface a designer reads.
        "designer" => {
            let store = match std::env::var("BSC_COMPONENT_KIT_DIR").ok().filter(|d| !d.is_empty()) {
                Some(dir) => Ok(bsc_json_store::Store::new(dir, "kit")),
                None => bsc_json_store::Store::open_default("kits", "kit"),
            };
            match store {
                Ok(st) => st
                    .list()
                    .iter()
                    .filter_map(|id| st.get(id).ok().flatten())
                    .filter_map(|raw| serde_json::from_str::<serde_json::Value>(&raw).ok())
                    .filter_map(|v| v.get("tech").and_then(|t| t.as_str()).map(str::to_string))
                    .collect(),
                Err(_) => Vec::new(),
            }
        }
        _ => Vec::new(),
    };
    // Sorted then deduped so the listing order is stable across runs: a store enumerates in whatever
    // order it enumerates, and `bsc session list` reordering itself between two invocations would read
    // as sessions appearing and disappearing.
    techs.sort();
    techs.dedup();
    techs
}

/// The studios that currently exist — the projection, against the axis above.
fn derived_sessions() -> Vec<bsc_session::ResolvedSession> {
    bsc_session::studio_sessions(studio_axis)
}

/// Resolve `id` the way the app must: the CLI's grammar FIRST (so a malformed id is refused with the
/// grammar's own message), then membership of the derived set.
///
/// **This is where the closed set closes.** `bsc_session::resolve` parses `librarianKlingon` because a
/// CLI process has no store to check it against; this refuses it, because the app does. The refusal
/// names what does exist rather than saying "unknown" — the same rule the CLI's own error follows.
fn resolve_existing(id: &str) -> Result<bsc_session::ResolvedSession, String> {
    let parsed = bsc_session::resolve(id)?;
    // A network architect, a network steward, a surface session: their own grammars answer for them
    // and no axis applies, so anything the studio projection does not claim passes through unchanged.
    if bsc_session::studio_session_kind(id).is_none() {
        return Ok(parsed);
    }
    let sessions = derived_sessions();
    if sessions.iter().any(|s| s.id == id) {
        return Ok(parsed);
    }
    Err(format!(
        "'{id}' is a well-formed studio id but no such studio exists — its technology has nothing to \
         curate, so no session is offered for it. The studios that exist right now: {}.\n\
         They are DERIVED from what the stores hold (`impl.tech` for a librarian, `kit.tech` for a \
         designer), so this one appears by itself the moment its technology has a record.",
        sessions.iter().map(|s| s.id.as_str()).collect::<Vec<_>>().join(" · ")
    ))
}

/// `bsc session list` — every system session's real state, answered in Rust, PLUS the sessions the app
/// is running that this verb does not manage.
///
/// Always reports the WHOLE registry, filtered by the request's ids when it names any. A session with
/// no PTY is reported as `live: false` rather than omitted: "not running" is an answer, and a missing
/// row would read as "this session does not exist".
///
/// # Why it reports beyond the registry
///
/// The registry is a CLOSED SET because that is what makes this verb safe to grant to the architect —
/// every argument is an id the app owns. But "what may I name?" and "what is running?" are different
/// questions, and answering only the first meant two `debug-studio:req-<n>` sessions could appear with
/// no `bsc` surface able to see them at all: the only way to find them was to grep the app's log for
/// `pty[debug-studio:`. That is a per-request debug session, whose id is MINTED AT RUNTIME and so can
/// never be a compile-time registry entry.
///
/// So the read widens and the write does not. Discovered rows carry `managed: false`, and `resolve`
/// still refuses their ids — not by a check here, but because those ids are not in the space it
/// searches.
pub fn list(app: &tauri::AppHandle, req: &SessionListRequest) -> Result<SessionListResult, String> {
    let wanted: Vec<bsc_session::ResolvedSession> = if req.ids.is_empty() {
        // THE PROJECTION, not a static table. This is the read that made `librarianPython` visible for
        // years: it walked a compile-time list, so a session for a technology with no records was
        // reported as an ordinary studio that merely happened not to be running.
        derived_sessions()
    } else {
        // An unknown id in the filter is DROPPED rather than erroring the whole read: `list` is the
        // command a caller runs to find out what the valid ids are, so failing it on a bad guess would
        // withhold exactly the information being asked for.
        req.ids.iter().filter_map(|id| resolve_existing(id).ok()).collect()
    };

    let state = app.state::<crate::console::pty::PtyState>();
    let liveness = crate::console::pty::pane_liveness(
        wanted.iter().map(|s| s.pane_id.to_string()).collect(),
        &state,
    );

    let mut sessions: Vec<SystemSessionState> = wanted
        .iter()
        .map(|s| {
            let live = liveness.iter().find(|p| p.pane_id == s.pane_id);
            SystemSessionState {
                id: s.id.to_string(),
                pane_id: s.pane_id.to_string(),
                live: live.is_some_and(|p| p.live),
                // The AGENT-level probe, not the shell-level one: `busy` is permanently true for an agent
                // session, so reporting it here made the column a restatement of `live`.
                busy: live.is_some_and(|p| p.working),
                pid: live.and_then(|p| p.pid),
                summary: s.summary.clone(),
                managed: true,
            }
        })
        .collect();

    // ...and the sessions the app is running that this verb does NOT manage.
    //
    // Only on an unfiltered read. `--ids` resolves against the closed registry, so a filtered read is
    // asking about named sessions and a discovered id could not have been named in the first place.
    //
    // An empty `pane_ids` means "every pane the app is tracking", which is the only way to find one:
    // there is no list of them anywhere, because they are minted per request.
    if req.ids.is_empty() {
        let mut discovered: Vec<SystemSessionState> =
            crate::console::pty::pane_liveness(vec![], &state)
                .into_iter()
                // DEAD ONES ARE DROPPED, unlike a registry row. A registry row reports `live: false`
                // because the caller asked about a session that is always meaningful to name; a
                // discovered one exists only because it is running, so an exited `req-157` is not a
                // stopped session — it is a session that is over, and listing it would grow the table
                // by one row per request ever filed.
                .filter(|p| p.live)
                .filter_map(|p| {
                    let (id, summary) = bsc_session::discovered(&p.pane_id)?;
                    let id_for_managed = id.clone();
                    Some(SystemSessionState {
                        id,
                        pane_id: p.pane_id.clone(),
                        live: true,
                        busy: p.working,
                        pid: p.pid,
                        summary,
                        // DERIVED, not asserted: `managed` means "the write half can name this",
                        // and the write half is `resolve`. A network's architect is discovered
                        // AND nameable, so a hard-coded false would have made the two disagree.
                        managed: bsc_session::resolve(&id_for_managed).is_ok(),
                    })
                })
                .collect();
        // Stable order, so a listing read twice does not appear to shuffle: the map behind
        // `pane_liveness` has no order of its own.
        discovered.sort_by(|a, b| a.pane_id.cmp(&b.pane_id));
        sessions.extend(discovered);
    }

    Ok(SessionListResult { sessions })
}

/// What the frontend sends back once it has applied the lifecycle change.
#[derive(Debug, Clone, Deserialize)]
pub struct LifecycleAck {
    pub id: String,
    /// Set when the frontend could not apply it at all (it threw).
    #[serde(default)]
    pub error: Option<String>,
    /// The outcome, as the frontend observed it — `started` / `already-running` / `stopped` /
    /// `not-running`.
    #[serde(default)]
    pub outcome: Option<bsc_session::LifecycleOutcome>,
}

/// In-flight lifecycle requests, keyed by request id.
pub type LifecyclePending = crate::app::ack::AckPending<LifecycleAck>;

/// Ask the frontend to start or stop a system session, and block until it acks.
pub fn apply(
    app: &tauri::AppHandle,
    id: &str,
    req: &LifecycleRequest,
) -> Result<LifecycleResult, String> {
    // THE BOUNDARY. Not a courtesy re-check: anything that can write the channel dir reaches this line,
    // so the closed set has to be enforced where the action happens, not only where the CLI parsed it.
    //
    // `resolve_existing` is the second half of that boundary since
    // `the-studio-session-set-is-derived-not-declared`: the CLI's grammar says the id is well formed,
    // and this says the studio actually exists. Only the app can make the second call, because only
    // the app holds the stores the technology axis is derived from.
    let session = match req.action {
        LifecycleAction::Start => resolve_existing(&req.id)?,
        LifecycleAction::Stop => {
            let s = resolve_existing(&req.id)?;
            bsc_session::resolve_stoppable(&req.id)?;
            s
        }
    };

    // Measured here rather than asked of the frontend: the store knows what it WANTS mounted, not
    // whether a PTY exists. Both halves are needed to answer "is it running" honestly — see the header.
    let pty_live = app
        .try_state::<crate::console::pty::PtyState>()
        .map(|st| crate::console::pty::pane_liveness(vec![session.pane_id.to_string()], &st))
        .and_then(|v| v.into_iter().next())
        .is_some_and(|p| p.live);

    let rx = crate::app::ack::register::<LifecycleAck>(app, id);

    let payload = serde_json::json!({
        "id": id,
        "sessionId": session.id,
        "paneId": session.pane_id,
        "action": match req.action { LifecycleAction::Start => "start", LifecycleAction::Stop => "stop" },
        // The frontend ORs this with its own `wantedStudios` view. Sent rather than re-derived there
        // because the store cannot see a PTY.
        "ptyLive": pty_live,
        // #the-loop-comes-out-an-ask-is-just-a-delivery: when this start exists to serve an ask, the
        // session comes up holding THE REQUEST ITSELF as its launch prompt. It used to be prose
        // telling the session to go run `bsc loop watch <n>` — an indirection to a rendezvous that,
        // measured across 23 loops, the callee entered zero times. The request is right here.
        // Null for an ordinary start, which is what keeps an ordinary open from re-greeting.
        "askDirective": req.request.clone(),
    });

    app.emit("bsc://session-lifecycle", payload)
        .map_err(|e| format!("cannot reach the frontend: {e}"))?;

    let ack = rx.recv_timeout(ACK_TIMEOUT).map_err(|_| {
        crate::app::ack::unregister::<LifecycleAck>(app, id); // don't leak the slot when nobody ever answers
        format!(
            "the frontend did not apply the {} within {}ms — is a window open, or was it mid-reload? \
             (the app IS running; this is not a 'no app' timeout)",
            match req.action { LifecycleAction::Start => "start", LifecycleAction::Stop => "stop" },
            ACK_TIMEOUT.as_millis()
        )
    })?;
    crate::app::ack::unregister::<LifecycleAck>(app, id);

    if let Some(e) = ack.error {
        return Err(e);
    }
    // No outcome means the frontend acked without saying what happened — which is indistinguishable
    // from a no-op that succeeded, and a caller acting on "started" when nothing started is the #4025
    // failure in a different costume. Refuse rather than invent one.
    let outcome = ack.outcome.ok_or_else(|| {
        format!(
            "the app acked the {} of '{}' without reporting an outcome — its state is unknown; \
             `bsc session list` shows what is actually running.",
            match req.action { LifecycleAction::Start => "start", LifecycleAction::Stop => "stop" },
            session.id
        )
    })?;

    Ok(LifecycleResult {
        id: session.id.to_string(),
        pane_id: session.pane_id.to_string(),
        outcome,
    })
}

/// The frontend's ack — delivers into the waiter registered by [`apply`].
pub(crate) fn system_session_ack(ack: LifecycleAck, state: tauri::State<'_, LifecyclePending>) {
    let tx = state.take(&ack.id);
    match tx {
        Some(tx) => {
            let _ = tx.send(ack);
        }
        None => log::debug!("session lifecycle: ack for {} had no waiter (timed out?)", ack.id),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use bsc_session::LifecycleOutcome;

    /// An ack delivers to exactly its own waiter and is consumed — two lifecycle requests in flight
    /// must not cross, or a caller would be told the wrong session started.
    #[test]
    fn an_ack_reaches_only_its_own_waiter() {
        let pending = LifecyclePending::default();
        let rx_a = pending.register("a");
        let rx_b = pending.register("b");
        let ack = LifecycleAck { id: "b".into(), error: None, outcome: Some(LifecycleOutcome::Started) };
        let id = ack.id.clone();
        assert!(pending.deliver(&id, ack), "the parked waiter must receive it");

        assert!(rx_b.try_recv().is_ok(), "b's waiter got its ack");
        assert!(rx_a.try_recv().is_err(), "a's waiter is untouched");
        assert!(pending.contains("a"), "a is still registered");
        assert!(!pending.contains("b"), "b was consumed");
    }

    /// The ack's outcome is the wire enum, so the frontend's kebab-case strings must deserialize into
    /// it. A silent mismatch here would surface as "acked without an outcome" for every request.
    #[test]
    fn the_frontends_outcome_strings_deserialize() {
        for (json, want) in [
            ("\"started\"", LifecycleOutcome::Started),
            ("\"already-running\"", LifecycleOutcome::AlreadyRunning),
            ("\"stopped\"", LifecycleOutcome::Stopped),
            ("\"not-running\"", LifecycleOutcome::NotRunning),
        ] {
            let ack: LifecycleAck =
                serde_json::from_str(&format!("{{\"id\":\"x\",\"outcome\":{json}}}")).unwrap();
            assert_eq!(ack.outcome, Some(want));
        }
    }

    /// An ack with no outcome parses (the field is optional on the wire) but `apply` turns it into an
    /// error rather than a fabricated success — pinned here because the parse succeeding is exactly
    /// what makes the omission easy to miss.
    #[test]
    fn an_ack_without_an_outcome_parses_but_carries_none() {
        let ack: LifecycleAck = serde_json::from_str("{\"id\":\"x\"}").unwrap();
        assert!(ack.outcome.is_none());
        assert!(ack.error.is_none());
    }

    /// A `stop` naming a director never reaches the emit: `apply` resolves against the closed set
    /// first. This is the app-side half of the guarantee the CLI also makes — both sides, because the
    /// channel dir is writable by anything on the machine.
    #[test]
    fn the_app_side_refuses_an_id_outside_the_closed_set() {
        for candidate in ["studio-code:director", "director", "worker", ""] {
            assert!(
                bsc_session::resolve(candidate).is_err(),
                "{candidate} must not resolve app-side either"
            );
        }
    }

    /// THE APP IS WHERE THE CLOSED SET CLOSES, and this is the case that only exists because the set is
    /// derived: an id the CLI's grammar accepts, for a studio that does not exist.
    ///
    /// `bsc_session::resolve` deliberately parses it — that crate is Tauri-free and its CLI holds no
    /// store, so it cannot know which technologies have records. If this half were missing, the
    /// grammar would be a genuine widening of the argument space rather than a relocation of the
    /// check, so the two assertions are written as a PAIR: the parse succeeds, and the app refuses.
    #[test]
    fn a_well_formed_id_for_a_studio_that_does_not_exist_is_refused_by_the_app() {
        assert!(
            bsc_session::resolve("librarianKlingon").is_ok(),
            "the CLI grammar parses it — that is the premise of this test, not an oversight"
        );
        let err = resolve_existing("librarianKlingon").unwrap_err();
        assert!(err.contains("no such studio exists"), "the refusal says WHY: {err}");
        assert!(err.contains("DERIVED"), "and says what would make it exist: {err}");
    }

    /// The grammars that are NOT studios pass straight through, or this check would break the network
    /// architects and surface sessions it knows nothing about.
    #[test]
    fn a_non_studio_grammar_is_not_subject_to_the_studio_axis() {
        for id in [
            "network-kitchen:architect",
            "network-kitchen:steward",
            "surface-studio:noun-plan",
            "surface-studio:verb-plan-list",
        ] {
            assert!(resolve_existing(id).is_ok(), "{id} must still resolve");
        }
    }
}

